 useEffect(()=>{if(!auth)return;const branchId=auth.memberships[0]?.branchId;if(!branchId)return;let active=true;const load=async()=>{try{const [configResponse,tableResponse]=await Promise.all([fetch(`/api/branch/config?branchId=${encodeURIComponent(branchId)}`),fetch(`/api/tables?branchId=${encodeURIComponent(branchId)}`)]);if(configResponse.ok){const data=await configResponse.json();if(active)setTaxRate(Number(data.branch.taxRate))}if(tableResponse.ok){const data=await tableResponse.json();if(active)setTables(data.tables)}}catch{}};const source=new EventSource(`/api/events?branchId=${encodeURIComponent(branchId)}`);const refresh=()=>{void load();window.dispatchEvent(new Event('table-session-updated'))};source.addEventListener('tables.changed',refresh);void load();const timer=window.setInterval(()=>void load(),30000);return()=>{active=false;source.close();window.clearInterval(timer)}},[auth]);
