 const subtotal=cart.reduce((s,l)=>s+l.food.price*l.qty,0), tax=cart.reduce((sum,line)=>{const amount=line.food.price*line.qty;const discountShare=subtotal?discount*amount/subtotal:0;return sum+Math.round((amount-discountShare)*line.taxRate/100)},0), total=Math.max(0,subtotal+tax-discount);
