      const data = await response.json() as { order: { number: number; createdAt: string; customerName: string; notes:string; table?:{number:string}|null; items: Array<{id:string;itemName:string;quantity: number;notes:string}>; total: string | number } };
      if (!response.ok) throw new Error((data as any).error?.message || 'Order could not be saved');
      const created: Order = { id: data.order.number, time: new Date(data.order.createdAt).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }), name: data.order.customerName, type: orderType, items: data.order.items.reduce((sum, line) => sum + line.quantity, 0), total: Number(data.order.total), status: 'Preparing', pay: 'Unpaid', tableNumber:data.order.table?.number??null, branchId,createdAt:data.order.createdAt,notes:data.order.notes,lines:data.order.items };
      setOrders(list => [created, ...list]);
