 const groups=Array.from((summary?.transactions||[]).reduce((map:Map<string,any>,row:any)=>{const key=`${row.direction}:${row.category}`;const group=map.get(key)||{key,direction:row.direction,category:row.category,amount:0,cashAmount:0,bankAmount:0,rows:[]};group.amount+=Number(row.amount);group[row.account==='CASH'?'cashAmount':'bankAmount']+=Number(row.amount);group.rows.push(row);map.set(key,group);return map},new Map<string,any>()).values()).sort((a:any,b:any)=>a.category.localeCompare(b.category));
 const download=(filename:string,content:string,type:string)=>{const url=URL.createObjectURL(new Blob([content],{type}));const anchor=document.createElement('a');anchor.href=url;anchor.download=filename;anchor.click();URL.revokeObjectURL(url)};
 const csvValue=(value:string|number)=>{let text=String(value);if(/^[\s]*[=+@\-]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`};
 const exportCsv=()=>{if(!summary)return;const rows:any[][]=[['Cashbook date range',from,to],['Opening cash',summary.openingCash],['Cash credits',summary.cashCredits],['Cash debits',summary.cashDebits],['Closing cash',summary.closingCash],['Opening bank',summary.openingBank],['Bank credits',summary.bankCredits],['Bank debits',summary.bankDebits],['Closing bank',summary.closingBank],[],['Date & time','Direction','Category','Account','Description','Amount'],...(summary.transactions||[]).map((row:any)=>[new Date(row.date).toLocaleString('en-IN'),row.direction,row.category,row.account==='CASH'?'Cash':'Bank',row.description,Number(row.amount)])];const csv='\ufeff'+rows.map(row=>row.map(csvValue).join(',')).join('\r\n');download(`cashbook-${from}-to-${to}.csv`,csv,'text/csv;charset=utf-8')};
