 const getRange=()=>{const now=new Date();if(range==='ALL')return{from:'',to:''};const days=range==='7D'?7:30;const from=new Date(now);from.setDate(from.getDate()-days+1);from.setHours(0,0,0,0);const to=new Date(now);to.setHours(23,59,59,999);return{from:from.toISOString(),to:to.toISOString()}};
