 const settle=async(event:React.FormEvent)=>{event.preventDefault();setError('');if(paymentMethod==='CASH'&&!cashSession){setError('Open the cash register from Cash Management before taking payment.');return}setBusy(true);try{const response=await fetch(`/api/table-sessions/${sessionId}/settle`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key.current},body:JSON.stringify({branchId,method:paymentMethod,...(paymentMethod==='CASH'?{cashReceived:Number(cashReceived).toFixed(2)}:{})})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Table payment could not be saved');onPaid();window.dispatchEvent(new Event('table-session-updated'));flash(`Table paid. Change due ${rupees(change)}`);const billResponse=await fetch(`/api/bills/table-session/${sessionId}?branchId=${encodeURIComponent(branchId)}`);const billData=await billResponse.json();if(!billResponse.ok)throw new Error(billData.error?.message||'Payment saved, but bill could not be loaded');setBill(billData.bill)}catch(err){setError(err instanceof Error?err.message:'Table payment could not be saved')}finally{setBusy(false)}};
 const print=async()=>{const win=window.open('','_blank','width=420,height=760');if(!win){setError('Allow pop-ups to print the bill.');return}try{const response=await fetch(`/api/bills/table-session/${sessionId}?branchId=${encodeURIComponent(branchId)}&print=1`);const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Bill could not be printed');const b=data.bill,s=b.session,orders=s.orders;const logo=s.branch.logoData?'<img class="receipt-logo" src="'+s.branch.logoData+'" alt="Restaurant logo">':'';const contact=receiptContactLines(s.branch);const lines=orders.flatMap((order:any)=>order.items.map((item:any)=>`<tr><td>${escapeReceiptText(item.itemName)}<small>${item.quantity} × ${rupees(Number(item.unitPrice))} · Tax ${Number(item.taxRate??0)}%</small></td><td>${rupees(Number(item.lineTotal))}</td></tr>`)).join('');const subtotal=orders.reduce((sum:number,o:any)=>sum+Number(o.subtotal),0),tax=orders.reduce((sum:number,o:any)=>sum+Number(o.taxAmount),0),total=orders.reduce((sum:number,o:any)=>sum+Number(o.total),0),allPayments=orders.flatMap((o:any)=>o.payments),payments=allPayments.reduce((sum:number,p:any)=>sum+Number(p.cashReceived??p.amount),0),changeGiven=allPayments.reduce((sum:number,p:any)=>sum+Number(p.changeGiven||0),0),discount=orders.reduce((sum:number,o:any)=>sum+Number(o.discount),0);win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Table bill ${b.number}</title><style>@page{size:80mm auto;margin:4mm}*{box-sizing:border-box}body{font:14px Arial,sans-serif;color:#111;width:72mm;margin:0 auto}header{text-align:center;padding:6px 0 10px}.invoice-title{font-weight:bold;border-top:1px dashed #333;border-bottom:1px dashed #333;padding:6px 0;margin-top:8px}.invoice-meta{padding-top:4px}.invoice-meta p{margin:4px 0}.receipt-logo{display:block;max-width:34mm;max-height:20mm;object-fit:contain;margin:0 auto 6px}h1{font-size:19px;margin:0 0 5px}p{margin:5px 0}.receipt-contact{font-size:12px;line-height:1.3}small{display:block;font-size:12px;margin-top:3px}table{width:100%;border-collapse:collapse;margin:10px 0}th,td{padding:5px 0;text-align:left;border-bottom:1px dotted #aaa}td:last-child,th:last-child{text-align:right}.totals{border-top:1px dashed #333;padding-top:7px}.totals p{display:flex;justify-content:space-between}.grand{font-size:17px;font-weight:bold}</style></head><body><header>${logo}<h1>${escapeReceiptText(s.branch.restaurant.name)}</h1><p>${escapeReceiptText(s.branch.name)}</p>${contact}<div class="invoice-title">Tax Invoice</div><div class="invoice-meta"><p>Bill #${b.number} · Table ${escapeReceiptText(s.table.number)}</p><p>${new Date(b.issuedAt).toLocaleString('en-IN')}</p><p>${escapeReceiptText(s.customerName)} · ${orders.length} order rounds</p></div></header><table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody>${lines}</tbody></table><section class="totals"><p><span>Subtotal</span><b>${rupees(subtotal)}</b></p>${discount>0?`<p><span>Discount</span><b>−${rupees(discount)}</b></p>`:''}<p><span>Tax</span><b>${rupees(tax)}</b></p><p class="grand"><span>Total</span><b>${rupees(total)}</b></p><p><span>Cash received</span><b>${rupees(payments)}</b></p><p><span>Change</span><b>${rupees(changeGiven)}</b></p></section><p style="text-align:center">Thank you. Please visit again.</p><script>window.onload=()=>{window.focus();window.print()}<\\/script></body></html>`);win.document.close()}catch(err){win.close();setError(err instanceof Error?err.message:'Bill could not be printed')}};
